// ① DCL：面试标准答案，instance 必须 volatile
public class DclSingleton {
    private static volatile DclSingleton instance;   // volatile 不能少

    private DclSingleton() {
        if (instance != null) {                       // 防反射（DCL 场景下的补丁）
            throw new IllegalStateException("already initialized");
        }
    }

    public static DclSingleton getInstance() {
        if (instance == null) {                       // 外层：避免每次都抢锁
            synchronized (DclSingleton.class) {
                if (instance == null) {               // 内层：防止重复创建
                    instance = new DclSingleton();
                }
            }
        }
        return instance;
    }
}

// ② 静态内部类：懒加载 + 线程安全 + 无锁（推荐）
public class HolderSingleton {
    private HolderSingleton() {}

    private static class Holder {                     // 外部类加载时不初始化
        private static final HolderSingleton INSTANCE = new HolderSingleton();
    }

    public static HolderSingleton getInstance() {
        return Holder.INSTANCE;                       // 首次调用才触发 Holder 初始化
    }
}

// ③ 枚举：防反射 + 防反序列化，写法最简
public enum EnumSingleton {
    INSTANCE;

    private final Map<String, String> config = new ConcurrentHashMap<>();

    public String get(String key) { return config.get(key); }
    public void put(String k, String v) { config.put(k, v); }
}

public final class HttpRequest {                 // final：不可变
    private final String url;                     // 必填
    private final String method;                  // 必填
    private final Map<String, String> headers;    // 可选
    private final byte[] body;                    // 可选
    private final int timeoutMs;                  // 可选，有默认值

    private HttpRequest(Builder b) {
        this.url = b.url;
        this.method = b.method;
        this.headers = Collections.unmodifiableMap(new HashMap<>(b.headers)); // 防外部修改
        this.body = b.body == null ? new byte[0] : b.body.clone();            // 防数组共享
        this.timeoutMs = b.timeoutMs;
    }

    public static Builder builder() { return new Builder(); }

    public static final class Builder {
        private String url;
        private String method = "GET";
        private final Map<String, String> headers = new LinkedHashMap<>();
        private byte[] body;
        private int timeoutMs = 3000;             // 默认值写在 Builder 里

        public Builder url(String url) { this.url = url; return this; }
        public Builder method(String m) { this.method = m; return this; }
        public Builder header(String k, String v) { headers.put(k, v); return this; }
        public Builder body(byte[] b) { this.body = b; return this; }
        public Builder timeoutMs(int ms) { this.timeoutMs = ms; return this; }

        public HttpRequest build() {
            Objects.requireNonNull(url, "url is required");     // 必填校验，集中在一处
            if (url.isEmpty()) throw new IllegalArgumentException("url is blank");
            if (timeoutMs <= 0) throw new IllegalArgumentException("timeoutMs must be > 0");
            if ("POST".equals(method) && (body == null || body.length == 0)) {
                throw new IllegalArgumentException("POST requires body");
            }
            return new HttpRequest(this);
        }
    }
}

