// ===== ① JDK 动态代理：必须有接口 =====
class JdkProxyDemo {
    @SuppressWarnings("unchecked")
    static <T> T proxy(T target, Class<T> iface) {
        return (T) Proxy.newProxyInstance(
            iface.getClassLoader(),
            new Class<?>[]{ iface },                      // 关键：靠接口「长得像」
            (p, method, args) -> {
                long t0 = System.nanoTime();
                try {
                    return method.invoke(target, args);    // 反射调用真实对象
                } finally {
                    System.out.println(method.getName()
                        + " cost " + (System.nanoTime() - t0) / 1000 + "us");
                }
            });
    }

    public static void main(String[] a) {
        UserService svc = proxy(new UserServiceImpl(), UserService.class);
        System.out.println(svc.find(1L));
        // svc instanceof UserServiceImpl  ->  false （$Proxy0 不是子类）
    }
}

// ===== ② CGLIB：靠继承，无需接口 =====
class CglibProxyDemo {
    @SuppressWarnings("unchecked")
    static <T> T proxy(Class<T> clazz) {
        Enhancer e = new Enhancer();
        e.setSuperclass(clazz);                            // 生成 clazz 的子类
        e.setCallback((MethodInterceptor) (obj, method, args, proxy) -> {
            System.out.println("before " + method.getName());
            Object r = proxy.invokeSuper(obj, args);        // 调父类（真实）方法
            System.out.println("after  " + method.getName());
            return r;
        });
        return (T) e.create();
    }

    public static void main(String[] a) {
        UserServiceImpl svc = proxy(UserServiceImpl.class);
        System.out.println(svc.find(2L));
        // svc instanceof UserServiceImpl  ->  true （是子类）
    }
}

// Component：叶子与容器的共同接口
interface FsNode {
    String name();
    long size();                       // 整体与部分都有意义
    default void print(String indent) { System.out.println(indent + name()); }
}

// Leaf：没有子节点
final class FsFile implements FsNode {
    private final String name;
    private final long bytes;

    FsFile(String name, long bytes) { this.name = name; this.bytes = bytes; }

    public String name() { return name; }
    public long size() { return bytes; }
}

// Composite：容器，行为 = 对子节点的递归
final class FsDir implements FsNode {
    private final String name;
    private final List<FsNode> children = new ArrayList<>();

    FsDir(String name) { this.name = name; }

    FsDir add(FsNode n) { children.add(n); return this; }   // 链式，只出现在 Composite 上（安全模式）

    public String name() { return name; }

    public long size() {
        long sum = 0;
        for (FsNode c : children) sum += c.size();           // 递归：叶子返回自身，容器继续下沉
        return sum;
    }

    public void print(String indent) {
        FsNode.super.print(indent);                          // 先打印自己
        for (FsNode c : children) c.print(indent + "  ");    // 再交给子节点，缩进加深
    }
}

// 客户端：只认 FsNode，不判类型
FsNode root = new FsDir("root")
        .add(new FsFile("a.txt", 100))
        .add(new FsDir("src")
                .add(new FsFile("Main.java", 2000))
                .add(new FsFile("Util.java", 800)))
        .add(new FsFile("b.log", 300));

System.out.println(root.size());     // 3200，一句搞定，没有 if-else
root.print("");

// 策略接口：自己声明「我是谁」，不靠 Bean 名硬编码
public interface PayStrategy {
    PayChannel channel();                 // 标识
    PayResult pay(PayRequest req);
}

@Component
public class AlipayStrategy implements PayStrategy {
    public PayChannel channel() { return PayChannel.ALIPAY; }
    public PayResult pay(PayRequest req) { /* ... */ return PayResult.ok(); }
}

@Component
public class WechatStrategy implements PayStrategy {
    public PayChannel channel() { return PayChannel.WECHAT; }
    public PayResult pay(PayRequest req) { /* ... */ return PayResult.ok(); }
}

// 注册 + 分发：
// Spring 会把所有 PayStrategy 实现注入成 List（顺序不确定，所以必须「按 channel() 建索引」）
@Component
public class PayStrategyRegistry {
    private final Map<PayChannel, PayStrategy> byChannel = new EnumMap<>(PayChannel.class);

    public PayStrategyRegistry(List<PayStrategy> all) {
        for (PayStrategy s : all) {
            PayStrategy prev = byChannel.put(s.channel(), s);
            if (prev != null) {                        // 启动即失败，别等线上才发现重复
                throw new IllegalStateException("duplicate strategy: " + s.channel());
            }
        }
    }

    public PayStrategy get(PayChannel c) {
        PayStrategy s = byChannel.get(c);
        if (s == null) throw new IllegalArgumentException("unsupported channel: " + c);
        return s;
    }
}

