// ① 回调接口：只暴露「变化的步骤」
@FunctionalInterface
interface StatementCallback<T> {
    T doInStatement(Connection conn) throws SQLException;
}

// ② 模板：流程固定（拿连接 → 执行 → 异常转换 → 释放），步骤由回调注入
public class MiniJdbcTemplate {
    private final DataSource dataSource;

    public MiniJdbcTemplate(DataSource ds) { this.dataSource = ds; }

    public <T> T execute(StatementCallback<T> action) {
        Connection conn = null;
        try {
            conn = dataSource.getConnection();          // ① 固定
            return action.doInStatement(conn);          // ② 变化（回调）
        } catch (SQLException e) {
            throw new DataAccessException("sql failed", e);   // ③ 固定：异常统一转换
        } finally {
            closeQuietly(conn);                         // ④ 固定：一定释放
        }
    }

    // 组合：模板 + 更具体的回调（设参 + 映射）
    public <T> List<T> query(String sql, Object[] args, RowMapper<T> mapper) {
        return execute(conn -> {
            try (PreparedStatement ps = conn.prepareStatement(sql)) {
                for (int i = 0; i < args.length; i++) ps.setObject(i + 1, args[i]);
                try (ResultSet rs = ps.executeQuery()) {
                    List<T> out = new ArrayList<>();
                    int row = 0;
                    while (rs.next()) out.add(mapper.mapRow(rs, row++));
                    return out;
                }
            }
        });
    }
}

