// ===== ① 反例：三层嵌套 + 一个 switch，改一处要读全篇 =====
public BigDecimal discount(Order o) {
    if (o != null) {
        if (o.getAmount() != null) {
            if (o.getAmount().compareTo(BigDecimal.ZERO) > 0) {
                switch (o.getUserLevel()) {
                    case NORMAL:  return o.getAmount();
                    case SILVER:  return o.getAmount().multiply(new BigDecimal("0.95"));
                    case GOLD:    return o.getAmount().multiply(new BigDecimal("0.90"));
                    case DIAMOND: return o.getAmount().multiply(new BigDecimal("0.85"));
                    default:      throw new IllegalArgumentException("unknown level");
                }
            }
            return BigDecimal.ZERO;
        }
        throw new IllegalArgumentException("amount is null");
    }
    throw new IllegalArgumentException("order is null");
}

// ===== ② 第一步：卫语句拆嵌套（成本最低，先做这一步）=====
public BigDecimal discount(Order o) {
    if (o == null) throw new IllegalArgumentException("order is null");
    if (o.getAmount() == null) throw new IllegalArgumentException("amount is null");
    if (o.getAmount().compareTo(BigDecimal.ZERO) <= 0) return BigDecimal.ZERO;

    return rateOf(o.getUserLevel()).multiply(o.getAmount());
}

// ===== ③ 第二步：把「level → 折扣率」变成表（枚举内建行为，比 Map 更类型安全）=====
public enum UserLevel {
    NORMAL("1.00"), SILVER("0.95"), GOLD("0.90"), DIAMOND("0.85");

    private final BigDecimal rate;
    UserLevel(String r) { this.rate = new BigDecimal(r); }
    public BigDecimal rate() { return rate; }
}

private static BigDecimal rateOf(UserLevel level) {
    if (level == null) throw new IllegalArgumentException("level is null");
    return level.rate();           // 没有 switch，加一种等级只在枚举里加一行
}

// ===== ① DFA 敏感词：Trie + 一次扫描 =====
class SensitiveWordFilter {
    private static class Node {
        Map<Character, Node> next = new HashMap<>();
        boolean end;                       // 是否是某个敏感词的结尾
    }

    private final Node root = new Node();

    public void add(String word) {
        Node cur = root;
        for (char c : word.toCharArray()) {
            cur = cur.next.computeIfAbsent(c, k -> new Node());
        }
        cur.end = true;
    }

    /** 把文本里所有命中位置替换成 *，O(len × 最长词长) */
    public String filter(String text) {
        char[] chars = text.toCharArray();
        int i = 0;
        while (i < chars.length) {
            Node cur = root;
            int j = i, lastEnd = -1;
            while (j < chars.length) {
                Node n = cur.next.get(chars[j]);
                if (n == null) break;       // 走不下去了
                cur = n;
                j++;
                if (cur.end) lastEnd = j;   // 记住「最长的命中」
            }
            if (lastEnd > 0) {
                for (int k = i; k < lastEnd; k++) chars[k] = '*';
                i = lastEnd;                // 命中后跳过这一段
            } else {
                i++;                        // 没命中，从下一个字符重新开始
            }
        }
        return new String(chars);
    }
}

// ===== ② 排行榜：ZSet + 同分按「先到先得」=====
// score 编码：高位是真分数，低位是「时间戳取反」（越早分越高）
private static double encode(long points, long tsMillis) {
    return points * 1e10 + (9_999_999_999L - tsMillis % 10_000_000_000L);
}

public void addScore(String uid, long points) {
    redis.opsForZSet().add("rank:2026-10-26", uid, encode(points, System.currentTimeMillis()));
}

public List<String> topN(int n) {
    Set<String> ids = redis.opsForZSet().reverseRange("rank:2026-10-26", 0, n - 1);
    return new ArrayList<>(ids);
}

public Long myRank(String uid) {
    Long r = redis.opsForZSet().reverseRank("rank:2026-10-26", uid);
    return r == null ? null : r + 1;    // Redis 从 0 开始
}

// ===== ① 流式 TopK：不占额外内存，一遍扫描 =====
public static List<String> topKStream(Iterator<String> it, int k) {
    // 小顶堆：堆顶是「当前第 K 名」，新元素只要比它大就有资格进榜
    PriorityQueue<Map.Entry<String, Integer>> heap =
            new PriorityQueue<>(k, Comparator.comparingInt(Map.Entry::getValue));

    Map<String, Integer> count = new HashMap<>();     // 这部分才是内存瓶颈
    while (it.hasNext()) {
        count.merge(it.next(), 1, Integer::sum);
    }
    for (Map.Entry<String, Integer> e : count.entrySet()) {
        if (heap.size() < k) {
            heap.offer(e);
        } else if (e.getValue() > heap.peek().getValue()) {
            heap.poll();                              // 淘汰「当前第 K 名」
            heap.offer(e);
        }
    }
    List<String> out = new ArrayList<>();
    while (!heap.isEmpty()) out.add(heap.poll().getKey());
    Collections.reverse(out);                         // 小顶堆弹出是「从小到大」
    return out;
}

// ===== ② 分治版：先分桶，再逐桶 TopK，最后归并 =====
public static List<String> topKPartitioned(Path bigFile, int k, int buckets) throws IOException {
    // step 1: 分桶（相同 key 必进同一桶）
    BufferedWriter[] ws = new BufferedWriter[buckets];
    for (int i = 0; i < buckets; i++) {
        ws[i] = Files.newBufferedWriter(Path.of("part-" + i));
    }
    try (BufferedReader r = Files.newBufferedReader(bigFile)) {
        String line;
        while ((line = r.readLine()) != null) {
            int idx = Math.floorMod(murmur3(line), buckets);   // 别用 String.hashCode
            ws[idx].write(line);
            ws[idx].newLine();
        }
    } finally {
        for (BufferedWriter w : ws) w.close();
    }

    // step 2 + 3: 逐桶统计 + 取 TopK，结果汇总后再归并
    PriorityQueue<Map.Entry<String, Integer>> global =
            new PriorityQueue<>(k, Comparator.comparingInt(Map.Entry::getValue));
    for (int i = 0; i < buckets; i++) {
        Map<String, Integer> local = new HashMap<>();
        try (BufferedReader r = Files.newBufferedReader(Path.of("part-" + i))) {
            String line;
            while ((line = r.readLine()) != null) local.merge(line, 1, Integer::sum);
        }
        for (Map.Entry<String, Integer> e : local.entrySet()) {
            if (global.size() < k) global.offer(e);
            else if (e.getValue() > global.peek().getValue()) {
                global.poll();
                global.offer(e);
            }
        }
    }
    List<String> out = new ArrayList<>();
    while (!global.isEmpty()) out.add(global.poll().getKey());
    Collections.reverse(out);
    return out;
}

// ❌ 反例：单例 Controller 把请求状态放成员变量
@RestController
public class BadController {
    private Long userId;                          // 状态挂在了单例上
    private final SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd");  // 有状态、非线程安全

    @GetMapping("/me")
    public String me(@RequestParam Long id) throws Exception {
        this.userId = id;                         // 线程 A 写 1，线程 B 写 2
        String now = sdf.format(new Date());      // 内部 Calendar 被并发改写
        return userId + " @ " + now;              // 可能返回 "2 @ ..." 给用户 1
    }
