// ① 迭代版：三个指针，顺序不能错（先存 next，再改 cur.next，最后整体后移）
public ListNode reverseList(ListNode head) {
    ListNode prev = null, cur = head;
    while (cur != null) {
        ListNode next = cur.next;   // 必须先存，否则改完指针就找不到后面了
        cur.next = prev;            // 反转当前指针
        prev = cur;                 // prev 前进
        cur = next;                 // cur 前进
    }
    return prev;                    // 注意返回 prev 不是 cur（cur 已经是 null）
}

// ② 递归版：想清「子问题已经反转好了，我只需要接上」
public ListNode reverseListRec(ListNode head) {
    if (head == null || head.next == null) return head;   // 空 or 单节点
    ListNode newHead = reverseListRec(head.next);         // 后面的已经反好了
    head.next.next = head;        // 让「后一个节点」指回来
    head.next = null;             // 断开原来的正向指针（不然成环）
    return newHead;
}

// ③ 区间反转 [left, right]（1-indexed）：哨兵 + 头插法，这是「K 个一组」的子过程
public ListNode reverseBetween(ListNode head, int left, int right) {
    ListNode dummy = new ListNode(0);
    dummy.next = head;
    ListNode prev = dummy;
    for (int i = 1; i < left; i++) prev = prev.next;   // prev 停在 left 的前一个
    ListNode cur = prev.next;
    for (int i = 0; i < right - left; i++) {           // 头插 right-left 次
        ListNode next = cur.next;
        cur.next = next.next;
        next.next = prev.next;
        prev.next = next;
    }
    return dummy.next;
}

public void quickSort(int[] a, int lo, int hi) {
    if (lo >= hi) return;                       // 0 或 1 个元素，天然有序

    // 随机化：防止「已排序数组」退化成 O(n^2) 并爆栈
    int pivotIdx = lo + ThreadLocalRandom.current().nextInt(hi - lo + 1);
    swap(a, lo, pivotIdx);
    int pivot = a[lo];

    // 三路分区：lt 左边全 < pivot，gt 右边全 > pivot，中间全 == pivot
    int lt = lo, i = lo + 1, gt = hi;
    while (i <= gt) {
        if (a[i] < pivot)      swap(a, lt++, i++);
        else if (a[i] > pivot) swap(a, i, gt--);   // 注意 i 不自增，换过来的还没看
        else                   i++;
    }
    quickSort(a, lo, lt - 1);
    quickSort(a, gt + 1, hi);
}

private void swap(int[] a, int i, int j) {
    int t = a[i]; a[i] = a[j]; a[j] = t;
}

// 对照记忆：归并排序（稳定，O(n) 额外空间，适合链表排序）
public void mergeSort(int[] a, int[] tmp, int lo, int hi) {
    if (lo >= hi) return;
    int mid = lo + (hi - lo) / 2;               // 不用 (lo+hi)/2，防溢出
    mergeSort(a, tmp, lo, mid);
    mergeSort(a, tmp, mid + 1, hi);
    int i = lo, j = mid + 1, k = lo;
    while (i <= mid && j <= hi) tmp[k++] = a[i] <= a[j] ? a[i++] : a[j++];  // <= 保证稳定
    while (i <= mid) tmp[k++] = a[i++];
    while (j <= hi) tmp[k++] = a[j++];
    System.arraycopy(tmp, lo, a, lo, hi - lo + 1);
}

class LRUCache {
    class Node {
        int k, v;
        Node prev, next;
        Node(int k, int v) { this.k = k; this.v = v; }
    }

    private final Map<Integer, Node> map = new HashMap<>();
    private final Node head = new Node(0, 0);   // 哨兵：最近使用
    private final Node tail = new Node(0, 0);   // 哨兵：最久未使用
    private final int capacity;

    public LRUCache(int capacity) {
        this.capacity = capacity;
        head.next = tail;
        tail.prev = head;
    }

    public int get(int key) {
        Node n = map.get(key);
        if (n == null) return -1;
        moveToHead(n);          // 关键：get 也算「用过」，必须刷新位置
        return n.v;
    }

    public void put(int key, int value) {
        Node n = map.get(key);
        if (n != null) {
            n.v = value;
            moveToHead(n);
            return;
        }
        if (map.size() == capacity) {
            Node lru = tail.prev;    // 最久未使用就是 tail 的前一个
            remove(lru);
            map.remove(lru.k);       // 别忘了从 map 里删，否则内存泄漏
        }
        Node node = new Node(key, value);
        map.put(key, node);
        addToHead(node);
    }

    private void moveToHead(Node n) { remove(n); addToHead(n); }

    private void remove(Node n) {
        n.prev.next = n.next;
        n.next.prev = n.prev;
    }

    private void addToHead(Node n) {
        n.next = head.next;
        n.prev = head;
        head.next.prev = n;
        head.next = n;
    }
}

// ① wait/notify：最底层，考点全在「while 不能写 if」
class Buffer1 {
    private final Queue<Integer> q = new LinkedList<>();
    private final int cap;
    Buffer1(int cap) { this.cap = cap; }

    public synchronized void put(int x) throws InterruptedException {
        while (q.size() == cap) wait();   // 必须是 while：被唤醒后要重新检查条件
        q.offer(x);
        notifyAll();                      // 用 notifyAll：notify 可能唤醒同类线程导致死锁
    }

    public synchronized int take() throws InterruptedException {
        while (q.isEmpty()) wait();
        int x = q.poll();
        notifyAll();
        return x;
    }
}

// ② BlockingQueue：工程首选，一行顶上面十行
class Buffer2 {
    private final BlockingQueue<Integer> q;
    Buffer2(int cap) { this.q = new ArrayBlockingQueue<>(cap); }
    public void put(int x) throws InterruptedException { q.put(x); }   // 满了自动阻塞
    public int take() throws InterruptedException { return q.take(); } // 空了自动阻塞
}

// ③ Condition + 两个等待队列：可以做到「精确唤醒生产者」而不是全员唤醒
class Buffer3 {
    private final Queue<Integer> q = new LinkedList<>();
    private final int cap;
    private final Lock lock = new ReentrantLock();
    private final Condition notFull  = lock.newCondition();
    private final Condition notEmpty = lock.newCondition();
    Buffer3(int cap) { this.cap = cap; }

    public void put(int x) throws InterruptedException {
        lock.lock();
        try {
            while (q.size() == cap) notFull.await();
            q.offer(x);
            notEmpty.signal();            // 只唤醒消费者，避免无谓的上下文切换
        } finally { lock.unlock(); }
    }

    public int take() throws InterruptedException {
        lock.lock();
        try {
            while (q.isEmpty()) notEmpty.await();
            int x = q.poll();
            notFull.signal();
            return x;
        } finally { lock.unlock(); }
    }
}

// 网格题的通用骨架：四方向 + 越界判断 + 原地标记（省掉 visited 数组）
private static final int[][] DIRS = {{1,0},{-1,0},{0,1},{0,-1}};

public int numIslands(char[][] grid) {
    int count = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[0].length; j++) {
            if (grid[i][j] == '1') {      // 遇到没访问过的陆地，就发现了一个新岛
                count++;
                dfs(grid, i, j);          // 把整块岛淹掉，避免重复计数
            }
        }
    }
    return count;
}

private void dfs(char[][] grid, int i, int j) {
    if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length) return;
    if (grid[i][j] != '1') return;        // 已经是水 / 已访问过
    grid[i][j] = '0';                     // 原地标记 = 淹掉，替代 visited
    for (int[] d : DIRS) dfs(grid, i + d[0], j + d[1]);
}

// 如果怕递归爆栈（超大网格），换 BFS：队列 + 入队时立刻标记
public int numIslandsBfs(char[][] grid) {
    int count = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[0].length; j++) {
            if (grid[i][j] != '1') continue;
            count++;
            Deque<int[]> q = new ArrayDeque<>();
            q.offer(new int[]{i, j});
            grid[i][j] = '0';             // 关键：入队时就标记，否则会重复入队
            while (!q.isEmpty()) {
                int[] cur = q.poll();
                for (int[] d : DIRS) {
                    int x = cur[0] + d[0], y = cur[1] + d[1];
                    if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length) continue;
                    if (grid[x][y] != '1') continue;
                    grid[x][y] = '0';     // 同一个坑：标记必须在 offer 之前
                    q.offer(new int[]{x, y});
                }
            }
        }
    }
    return count;
}

// ① 整体反转：三指针轮转的标准骨架
public ListNode reverse(ListNode head) {
    ListNode prev = null, cur = head;
    while (cur != null) {
        ListNode next = cur.next;   // 存
        cur.next = prev;            // 改
        prev = cur; cur = next;     // 移
    }
    return prev;                    // cur 为 null 时，prev 是新头
}

// ② 区间反转 [left, right]：用「头插法」代替双指针轮转，边界更干净
public ListNode reverseBetween(ListNode head, int left, int right) {
    ListNode dummy = new ListNode(0, head);   // 哨兵：left == 1 时不用特判
    ListNode prev = dummy;
    for (int i = 1; i < left; i++) prev = prev.next;
    ListNode cur = prev.next;
    for (int i = 0; i < right - left; i++) {
        ListNode next = cur.next;      // cur 始终是「区间里的第一个」，不动
        cur.next = next.next;          // 把 next 从 cur 后面摘掉
        next.next = prev.next;         // next 插到 prev 后面（区间头部）
        prev.next = next;
    }
    return dummy.next;
}

// ③ K 个一组翻转：外层「数够不够」，内层就是 ② 的区间反转
public ListNode reverseKGroup(ListNode head, int k) {
    ListNode dummy = new ListNode(0, head);
    ListNode groupPrev = dummy;

    while (true) {
        // 先数 k 个，数不够就结束（不足 k 个保持原序，这是题目要求）
        ListNode kth = groupPrev;
        for (int i = 0; i < k && kth != null; i++) kth = kth.next;
        if (kth == null) break;                // 剩余不足 k 个

        ListNode groupNext = kth.next;         // 记住这一组之后的位置
        ListNode prev = groupNext;             // 关键：新头的 next 要指向 groupNext
        ListNode cur = groupPrev.next;
        while (cur != groupNext) {             // 只反转这一组
            ListNode next = cur.next;
            cur.next = prev;
            prev = cur;
            cur = next;
        }
        ListNode newGroupTail = groupPrev.next; // 反转前的组头 = 反转后的组尾
        groupPrev.next = prev;                  // 接上反转后的新头
        groupPrev = newGroupTail;               // 下一组的前驱
    }
    return dummy.next;
}

public ListNode detectCycle(ListNode head) {
    ListNode slow = head, fast = head;
    while (fast != null && fast.next != null) {
        slow = slow.next;
        fast = fast.next.next;
        if (slow == fast) {              // 相遇：说明有环
            // 关键一步：一个指针回头节点，两人都改成每次走一步
            ListNode p = head;
            while (p != slow) {
                p = p.next;
                slow = slow.next;
            }
            return p;                    // 再相遇处就是入口
        }
    }
    return null;                         // 无环
}

// 相交链表：走完自己的路，去走对方的路
public ListNode getIntersectionNode(ListNode headA, ListNode headB) {
    ListNode a = headA, b = headB;
    while (a != b) {
        a = (a == null) ? headB : a.next;   // 注意：是「变为 null 之后」才换头
        b = (b == null) ? headA : b.next;
    }
    return a;                               // 有交点则返回交点；无交点则同时为 null
}

// 基础件：合并两个有序链表（哨兵 + 尾指针，这题必须能默写）
public ListNode mergeTwo(ListNode a, ListNode b) {
    ListNode dummy = new ListNode(0), tail = dummy;
    while (a != null && b != null) {
        if (a.val <= b.val) { tail.next = a; a = a.next; }   // <= 保证稳定
        else                { tail.next = b; b = b.next; }
        tail = tail.next;
    }
    tail.next = (a != null) ? a : b;    // 剩下的直接接上，不用循环
    return dummy.next;
}

// 排序链表：切分（找中点 + 断链）→ 递归两半 → 合并
public ListNode sortList(ListNode head) {
    if (head == null || head.next == null) return head;   // 0 或 1 个节点

    // 找中点：用「前中」，否则两个节点时会死循环（slow 永远停在 head）
    ListNode slow = head, fast = head.next;
    while (fast != null && fast.next != null) {
        slow = slow.next;
        fast = fast.next.next;
    }
    ListNode mid = slow.next;
    slow.next = null;                 // 关键：必须断链，否则递归永不收敛

    ListNode left = sortList(head);
    ListNode right = sortList(mid);
    return mergeTwo(left, right);
}

// 自底向上归并（O(1) 空间）：按步长 1,2,4,8... 两两合并
public ListNode sortListBottomUp(ListNode head) {
    if (head == null || head.next == null) return head;
    int n = 0;
    for (ListNode p = head; p != null; p = p.next) n++;

    ListNode dummy = new ListNode(0, head);
    for (int step = 1; step < n; step <<= 1) {      // 步长翻倍
        ListNode prev = dummy, cur = dummy.next;
        while (cur != null) {
            ListNode left = cur, right = split(left, step);
            cur = split(right, step);               // cur 指向下一对的开头
            prev = mergeInPlace(prev, left, right); // 返回合并后的尾节点
        }
    }
    return dummy.next;
}

// 从 head 起切下 len 个节点，返回「切完之后的下一个」
private ListNode split(ListNode head, int len) {
    if (head == null) return null;
    for (int i = 1; i < len && head.next != null; i++) head = head.next;
    ListNode rest = head.next;
    head.next = null;
    return rest;
}

// 把 left、right 两条链合并后接在 prev 后面，返回合并后的尾节点
private ListNode mergeInPlace(ListNode prev, ListNode left, ListNode right) {
    ListNode cur = prev;
    while (left != null && right != null) {
        if (left.val <= right.val) { cur.next = left;  left = left.next; }
        else                       { cur.next = right; right = right.next; }
        cur = cur.next;
    }
    cur.next = (left != null) ? left : right;
    while (cur.next != null) cur = cur.next;   // 走到真正的尾部
    return cur;
}

public List<List<Integer>> threeSum(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    Arrays.sort(nums);                          // 前提：排序（返回的是值，不是下标）
    int n = nums.length;

    for (int i = 0; i < n - 2; i++) {
        if (nums[i] > 0) break;                 // 剪枝：最小的都 > 0，后面不可能凑成 0
        if (i > 0 && nums[i] == nums[i - 1]) continue;   // 去重①：跳过重复的第一个数

        int l = i + 1, r = n - 1;
        while (l < r) {
            int sum = nums[i] + nums[l] + nums[r];
            if (sum < 0) {
                l++;
            } else if (sum > 0) {
                r--;
            } else {
                res.add(Arrays.asList(nums[i], nums[l], nums[r]));
                // 去重②③：找到一组后，l 和 r 各自跳过连续重复
                while (l < r && nums[l] == nums[l + 1]) l++;
                while (l < r && nums[r] == nums[r - 1]) r--;
                l++; r++;
            }
        }
    }
    return res;
}

// 求最短：满足条件就缩，缩之前先更新答案
public int minSubArrayLen(int target, int[] nums) {
    int l = 0, sum = 0, ans = Integer.MAX_VALUE;
    for (int r = 0; r < nums.length; r++) {
        sum += nums[r];                        // 扩张
        while (sum >= target) {                // 满足条件 → 开始缩
            ans = Math.min(ans, r - l + 1);    // 先更新答案（此刻是一个候选最短）
            sum -= nums[l++];                  // 再缩
        }
    }
    return ans == Integer.MAX_VALUE ? 0 : ans; // 从没满足过 → 返回 0
}

// 求最长：不合法就缩，缩完之后再更新答案
public int lengthOfLongestSubstring(String s) {
    Map<Character, Integer> last = new HashMap<>();
    int l = 0, ans = 0;
    for (int r = 0; r < s.length(); r++) {
        char c = s.charAt(r);
        Integer prev = last.get(c);
        if (prev != null && prev >= l) {       // 重复点在窗口内
            l = prev + 1;                      // 直接跳到重复点之后（不是 l++）
        }
        last.put(c, r);
        ans = Math.max(ans, r - l + 1);        // 此时窗口一定合法，可以更新
    }
    return ans;
}

// 变体：最多包含 k 种不同字符的最长子串（同一模板，条件换成「种类数 <= k」）
public int lengthOfLongestKDistinct(String s, int k) {
    Map<Character, Integer> cnt = new HashMap<>();
    int l = 0, ans = 0;
    for (int r = 0; r < s.length(); r++) {
        cnt.merge(s.charAt(r), 1, Integer::sum);
        while (cnt.size() > k) {               // 不合法：种类超了
            char c = s.charAt(l++);
            if (cnt.merge(c, -1, Integer::sum) == 0) cnt.remove(c);
        }
        ans = Math.max(ans, r - l + 1);
    }
    return ans;
}

// 前缀和 + 哈希：O(n) 时间、O(n) 空间（含负数也成立）
public int subarraySum(int[] nums, int k) {
    Map<Integer, Integer> cnt = new HashMap<>();
    cnt.put(0, 1);                  // 空前缀：代表「区间从 0 开始」这种情况
    int pre = 0, ans = 0;
    for (int x : nums) {
        pre += x;                                  // 当前前缀和 pre[j]
        ans += cnt.getOrDefault(pre - k, 0);       // 有多少个 pre[i] == pre[j] - k
        cnt.merge(pre, 1, Integer::sum);
    }
    return ans;
}

// 二维前缀和：pre[i][j] = 左上角 (0,0) 到 (i-1,j-1) 的矩形和
// 求 (r1,c1) 到 (r2,c2) 的矩形和（含端点）
class MatrixSum {
    private final int[][] pre;
    MatrixSum(int[][] m) {
        int R = m.length, C = m[0].length;
        pre = new int[R + 1][C + 1];
        for (int i = 1; i <= R; i++)
            for (int j = 1; j <= C; j++)
                pre[i][j] = pre[i-1][j] + pre[i][j-1] - pre[i-1][j-1] + m[i-1][j-1];
    }
    int query(int r1, int c1, int r2, int c2) {   // 传 0-indexed，含端点
        return pre[r2+1][c2+1] - pre[r1][c2+1] - pre[r2+1][c1] + pre[r1][c1];
    }
}

// 差分数组：把「区间 [l, r] 全部加 v」从 O(n) 降到 O(1)，最后一遍前缀和还原
class DiffArray {
    private final int[] d;
    DiffArray(int n) { d = new int[n + 1]; }
    void add(int l, int r, int v) { d[l] += v; if (r + 1 < d.length) d[r + 1] -= v; }
    int[] build() {
        int[] a = new int[d.length - 1];
        int cur = 0;
        for (int i = 0; i < a.length; i++) { cur += d[i]; a[i] = cur; }
        return a;
    }
}

// ===== 递归三兄弟（顺序只差一行）=====
void preorder(TreeNode n, List<Integer> out)  { if (n == null) return; out.add(n.val); preorder(n.left, out);  preorder(n.right, out); }
void inorder(TreeNode n, List<Integer> out)   { if (n == null) return; inorder(n.left, out);  out.add(n.val); inorder(n.right, out); }
void postorder(TreeNode n, List<Integer> out) { if (n == null) return; postorder(n.left, out); postorder(n.right, out); out.add(n.val); }

// ===== 迭代前序：栈 + 「右先入、左后入」（因为栈是后进先出）
List<Integer> preorderIt(TreeNode root) {
    List<Integer> out = new ArrayList<>();
    if (root == null) return out;
    Deque<TreeNode> st = new ArrayDeque<>();
    st.push(root);
    while (!st.isEmpty()) {
        TreeNode n = st.pop();
        out.add(n.val);
        if (n.right != null) st.push(n.right);   // 先压右
        if (n.left != null)  st.push(n.left);    // 后压左 → 下次先弹出左
    }
    return out;
}

// ===== 迭代中序：栈 + 指针（唯一需要「一路压左」的写法）
List<Integer> inorderIt(TreeNode root) {
    List<Integer> out = new ArrayList<>();
    Deque<TreeNode> st = new ArrayDeque<>();
    TreeNode cur = root;
    while (cur != null || !st.isEmpty()) {   // 两个条件缺一不可
        while (cur != null) {                // 一路向左，全部压栈
            st.push(cur);
            cur = cur.left;
        }
        cur = st.pop();                      // 弹出 = 最左的未访问节点
        out.add(cur.val);
        cur = cur.right;                     // 转向右子树（可能为 null，下一轮会再弹栈）
    }
    return out;
}

// ===== 迭代后序：按「根右左」遍历再反转，或用双栈
List<Integer> postorderIt(TreeNode root) {
    LinkedList<Integer> out = new LinkedList<>();
    if (root == null) return out;
    Deque<TreeNode> st = new ArrayDeque<>();
    st.push(root);
    while (!st.isEmpty()) {
        TreeNode n = st.pop();
        out.addFirst(n.val);                 // 头插 = 逆序，等价于最后反转
        if (n.left != null)  st.push(n.left);   // 注意：先压左
        if (n.right != null) st.push(n.right);  // 后压右
    }
    return out;
}

// ===== 层序：队列 + 「先记每层长度」
List<List<Integer>> levelOrder(TreeNode root) {
    List<List<Integer>> res = new ArrayList<>();
    if (root == null) return res;
    Deque<TreeNode> q = new ArrayDeque<>();
    q.offer(root);
    while (!q.isEmpty()) {
        int size = q.size();                 // 关键：先记下来，这一轮只处理这么多
        List<Integer> level = new ArrayList<>(size);
        for (int i = 0; i < size; i++) {
            TreeNode n = q.poll();
            level.add(n.val);
            if (n.left != null)  q.offer(n.left);
            if (n.right != null) q.offer(n.right);
        }
        res.add(level);
    }
    return res;
}

// ❌ 前序式写法：每个节点都重新算一次高度 → O(n^2)
public boolean isBalancedSlow(TreeNode root) {
    if (root == null) return true;
    int lh = height(root.left), rh = height(root.right);   // 每次都完整遍历子树
    return Math.abs(lh - rh) <= 1
        && isBalancedSlow(root.left)                        // 子树又各自重算高度
        && isBalancedSlow(root.right);
}
private int height(TreeNode n) {
    return n == null ? 0 : 1 + Math.max(height(n.left), height(n.right));
}

// ✅ 后序式写法：一次遍历，用 -1 表示「已经不平衡」→ O(n)
public boolean isBalanced(TreeNode root) {
    return dfs(root) != -1;
}
private int dfs(TreeNode n) {
    if (n == null) return 0;
    int lh = dfs(n.left);
    if (lh == -1) return -1;          // 剪枝：左子树已经不平衡，直接向上传
    int rh = dfs(n.right);
    if (rh == -1) return -1;          // 剪枝：右子树不平衡
    if (Math.abs(lh - rh) > 1) return -1;
    return 1 + Math.max(lh, rh);      // 返回「高度」给父节点用
}

// 对照：最大深度（Q35）——后序三行，注意和「最小深度」的区别
public int maxDepth(TreeNode root) {
    if (root == null) return 0;
    return 1 + Math.max(maxDepth(root.left), maxDepth(root.right));
}

// 最小深度：注意「单边为 null」不能直接取 min（那条路根本不通向叶子）
public int minDepth(TreeNode root) {
    if (root == null) return 0;
    if (root.left == null) return 1 + minDepth(root.right);   // 只有右子树
    if (root.right == null) return 1 + minDepth(root.left);   // 只有左子树
    return 1 + Math.min(minDepth(root.left), minDepth(root.right));
}

// 最近公共祖先：返回值三态（null / 找到的一个 / LCA 本身）
public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
    if (root == null || root == p || root == q) return root;   // 终止：空 或 命中
    TreeNode left  = lowestCommonAncestor(root.left,  p, q);
    TreeNode right = lowestCommonAncestor(root.right, p, q);
    if (left != null && right != null) return root;   // 分居两侧 → 当前就是 LCA
    return left != null ? left : right;               // 只有一侧找到 → 继续往上带
}

// 二叉树最大路径和：返回「一条腿」，答案是「两条腿 + 自己」
class MaxPathSum {
    private int ans = Integer.MIN_VALUE;   // 注意：不能初始化成 0（节点值可能全为负）

    public int maxPathSum(TreeNode root) {
        gain(root);
        return ans;
    }

    // 返回：以 n 为起点、向下延伸的最大「单边」贡献（不拐弯）
    private int gain(TreeNode n) {
        if (n == null) return 0;
        int left  = Math.max(gain(n.left),  0);   // 负数贡献直接丢弃（不走那条路）
        int right = Math.max(gain(n.right), 0);
        // 在这里「拐弯」：左 + 自己 + 右，作为一个候选答案
        ans = Math.max(ans, n.val + left + right);
        // 但返回给父节点的只能是「一条腿」
        return n.val + Math.max(left, right);
    }
}

// ① 标准查找：命中即返回
public int search(int[] a, int target) {
    int l = 0, r = a.length - 1;
    while (l <= r) {
        int mid = l + (r - l) / 2;
        if (a[mid] == target) return mid;
        if (a[mid] < target) l = mid + 1;
        else                 r = mid - 1;
    }
    return -1;
}

// ② 左边界：第一个 >= target 的位置（不存在则返回 a.length）
public int lowerBound(int[] a, int target) {
    int l = 0, r = a.length - 1;
    while (l <= r) {
        int mid = l + (r - l) / 2;
        if (a[mid] >= target) r = mid - 1;   // 命中也不停，继续往左找
        else                  l = mid + 1;
    }
    return l;                                 // l 是「第一个 >= target」的位置
}

// ③ 右边界：最后一个 <= target 的位置（不存在则返回 -1）
public int upperBound(int[] a, int target) {
    int l = 0, r = a.length - 1;
    while (l <= r) {
        int mid = l + (r - l) / 2;
        if (a[mid] <= target) l = mid + 1;    // 命中也不停，继续往右找
        else                  r = mid - 1;
    }
    return l - 1;                             // l 是「第一个 > target」，所以减 1
}

// ④ Q57：在排序数组中查找元素的第一个和最后一个位置
public int[] searchRange(int[] nums, int target) {
    int left = lowerBound(nums, target);
    // 不存在的情况：越界，或该位置的值不等于 target
    if (left == nums.length || nums[left] != target) return new int[]{-1, -1};
    int right = upperBound(nums, target);     // 这里 upperBound 一定能找到
    return new int[]{left, right};
}

// ⑤ 二分查找的「插入位置」（就是 lowerBound 的语义）
public int searchInsert(int[] nums, int target) {
    return lowerBound(nums, target);
}

// 无重复元素：O(log n)
public int searchRotated(int[] a, int target) {
    int l = 0, r = a.length - 1;
    while (l <= r) {
        int mid = l + (r - l) / 2;
        if (a[mid] == target) return mid;
        if (a[l] <= a[mid]) {                       // 左半 [l, mid] 有序
            if (a[l] <= target && target < a[mid]) r = mid - 1;   // target 在左半
            else                                   l = mid + 1;
        } else {                                     // 右半 [mid, r] 有序
            if (a[mid] < target && target <= a[r]) l = mid + 1;   // target 在右半
            else                                   r = mid - 1;
        }
    }
    return -1;
}

// 有重复元素：最坏 O(n)（无法判断有序侧时各缩一步）
public boolean searchRotatedWithDup(int[] a, int target) {
    int l = 0, r = a.length - 1;
    while (l <= r) {
        int mid = l + (r - l) / 2;
        if (a[mid] == target) return true;
        if (a[l] == a[mid] && a[mid] == a[r]) {     // 三处相同：无法判断
            l++; r--;                               // 只能线性收缩
        } else if (a[l] <= a[mid]) {                // 左半有序
            if (a[l] <= target && target < a[mid]) r = mid - 1;
            else                                   l = mid + 1;
        } else {                                     // 右半有序
            if (a[mid] < target && target <= a[r]) l = mid + 1;
            else                                   r = mid - 1;
        }
    }
    return false;
}

// 模板：求「最小的可行值」
// while (l < r) { mid; if (check(mid)) r = mid; else l = mid + 1; } return l;

// 例 1：在 D 天内送达包裹的最低载重能力
public int shipWithinDays(int[] weights, int D) {
    int l = 0, r = 0;
    for (int w : weights) { l = Math.max(l, w); r += w; }   // 下界=最重单件，上界=总和
    while (l < r) {
        int mid = l + (r - l) / 2;
        if (daysNeeded(weights, mid) <= D) r = mid;          // 可行 → 试更小的
        else                               l = mid + 1;
    }
    return l;
}
private int daysNeeded(int[] w, int cap) {
    int days = 1, cur = 0;
    for (int x : w) {
        if (cur + x > cap) { days++; cur = 0; }              // 装不下就开新船
        cur += x;
    }
    return days;
}

// 例 2：分割数组的最大值最小（把数组切成 m 段，使「各段和的最大值」最小）
public int splitArray(int[] nums, int m) {
    int l = 0, r = 0;
    for (int x : nums) { l = Math.max(l, x); r += x; }
    while (l < r) {
        int mid = l + (r - l) / 2;
        if (canSplit(nums, m, mid)) r = mid;
        else                        l = mid + 1;
    }
    return l;
}
private boolean canSplit(int[] nums, int m, int maxSum) {
    int cnt = 1, cur = 0;
    for (int x : nums) {
        if (cur + x > maxSum) { cnt++; cur = 0; }
        cur += x;
    }
    return cnt <= m;                    // 段数不超过 m 就可行（合并两段只会更小）
}

// 例 3：K 小时内吃完香蕉的最小速度
public int minEatingSpeed(int[] piles, int h) {
    int l = 1, r = 0;
    for (int p : piles) r = Math.max(r, p);   // 上界=最大堆（1 小时吃完一堆）
    while (l < r) {
        int mid = l + (r - l) / 2;
        if (hoursNeeded(piles, mid) <= h) r = mid;
        else                              l = mid + 1;
    }
    return l;
}
private long hoursNeeded(int[] piles, int k) {
    long h = 0;
    for (int p : piles) h += (p + k - 1) / k;   // 向上取整：吃完一堆要 ceil(p/k) 小时
    return h;
}

// 三路快排：把「等于 pivot」的一段一次排好，重复元素也不退化
public void quickSort(int[] a, int lo, int hi) {
    if (lo >= hi) return;
    int p = lo + ThreadLocalRandom.current().nextInt(hi - lo + 1);
    swap(a, lo, p);
    int pivot = a[lo];

    int lt = lo, i = lo + 1, gt = hi;
    while (i <= gt) {
        if      (a[i] < pivot) swap(a, lt++, i++);
        else if (a[i] > pivot) swap(a, i, gt--);   // i 不自增：换过来的还没看
        else                   i++;
    }
    quickSort(a, lo, lt - 1);     // 只递归「小于」段和「大于」段
    quickSort(a, gt + 1, hi);     // 「等于 pivot」的 [lt, gt] 已经就位
}
private void swap(int[] a, int i, int j) { int t = a[i]; a[i] = a[j]; a[j] = t; }

// 归并排序：稳定；能在合并时顺带统计逆序对
public int mergeSortCount(int[] a) {
    return merge(a, new int[a.length], 0, a.length - 1);
}
private int merge(int[] a, int[] tmp, int lo, int hi) {
    if (lo >= hi) return 0;
    int mid = lo + (hi - lo) / 2;
    int cnt = merge(a, tmp, lo, mid) + merge(a, tmp, mid + 1, hi);

    int i = lo, j = mid + 1, k = lo;
    while (i <= mid && j <= hi) {
        if (a[i] <= a[j]) {
            tmp[k++] = a[i++];              // <= 保证稳定
        } else {
            tmp[k++] = a[j++];
            cnt += mid - i + 1;             // 关键：a[i..mid] 全都 > a[j]，构成逆序对
        }
    }
    while (i <= mid) tmp[k++] = a[i++];
    while (j <= hi)  tmp[k++] = a[j++];
    System.arraycopy(tmp, lo, a, lo, hi - lo + 1);
    return cnt;
}

// 手写大顶堆（数组实现，下标 0 开始，孩子是 2i+1 / 2i+2）
class MaxHeap {
    private int[] a; private int size;
    MaxHeap(int cap) { a = new int[cap]; }

    void push(int v) {
        a[size] = v;
        siftUp(size++);
    }
    int pop() {
        int top = a[0];
        a[0] = a[--size];            // 末尾元素提到堆顶
        siftDown(0);
        return top;
    }
    private void siftUp(int i) {
        while (i > 0) {
            int p = (i - 1) / 2;
            if (a[p] >= a[i]) break;
            swap(i, p);
            i = p;
        }
    }
    private void siftDown(int i) {
        while (true) {
            int l = 2 * i + 1, r = l + 1, m = i;
            if (l < size && a[l] > a[m]) m = l;
            if (r < size && a[r] > a[m]) m = r;   // 必须比较两个孩子
            if (m == i) break;
            swap(i, m);
            i = m;
        }
    }
    private void swap(int i, int j) { int t = a[i]; a[i] = a[j]; a[j] = t; }
}

// 堆排序：建堆 O(n) + n 次「取堆顶放末尾」O(n log n)，总 O(n log n)、原地
public void heapSort(int[] a) {
    int n = a.length;
    for (int i = n / 2 - 1; i >= 0; i--) siftDown(a, i, n);   // 建堆：从最后非叶子往前
    for (int end = n - 1; end > 0; end--) {
        swap(a, 0, end);                 // 堆顶（最大）换到末尾
        siftDown(a, 0, end);             // 在 [0, end) 内恢复堆序
    }
}
private void siftDown(int[] a, int i, int n) {
    while (true) {
        int l = 2 * i + 1, r = l + 1, m = i;
        if (l < n && a[l] > a[m]) m = l;
        if (r < n && a[r] > a[m]) m = r;
        if (m == i) break;
        swap(a, i, m);
        i = m;
    }
}
private void swap(int[] a, int i, int j) { int t = a[i]; a[i] = a[j]; a[j] = t; }

// 快速选择（QuickSelect）：期望 O(n) 找第 k 小（0-indexed）
public int quickSelect(int[] a, int k) {
    int lo = 0, hi = a.length - 1;
    ThreadLocalRandom rnd = ThreadLocalRandom.current();
    while (true) {
        if (lo == hi) return a[lo];
        int p = lo + rnd.nextInt(hi - lo + 1);
        swap(a, lo, p);
        int pivot = a[lo], lt = lo, i = lo + 1, gt = hi;
        while (i <= gt) {                        // 三路分区
            if      (a[i] < pivot) swap(a, lt++, i++);
            else if (a[i] > pivot) swap(a, i, gt--);
            else                   i++;
        }
        if (k < lt)       hi = lt - 1;           // 答案在「小」段
        else if (k > gt)  lo = gt + 1;           // 答案在「大」段
        else              return pivot;          // k 落在「等于 pivot」段
    }
}

// ① 有效括号：左括号入栈「期待配对的那个右括号」
public boolean isValid(String s) {
    Deque<Character> st = new ArrayDeque<>();
    for (char c : s.toCharArray()) {
        if (c == '(')      st.push(')');
        else if (c == '[') st.push(']');
        else if (c == '{') st.push('}');
        else if (st.isEmpty() || st.pop() != c) return false;   // 栈空 或 不匹配
    }
    return st.isEmpty();      // 必须清空，否则是 "[" 这种未闭合
}

// ② 最小栈：辅助栈同步记录「到目前为止的最小值」
class MinStack {
    private final Deque<Integer> data = new ArrayDeque<>();
    private final Deque<Integer> mins = new ArrayDeque<>();   // 栈顶 = 当前最小

    public void push(int v) {
        data.push(v);
        mins.push(mins.isEmpty() ? v : Math.min(v, mins.peek()));   // 注意是跟「栈顶」比
    }
    public void pop() {
        data.pop();
        mins.pop();                 // 两个栈必须同步弹，否则最小值会错位
    }
    public int top()    { return data.peek(); }
    public int getMin() { return mins.peek(); }
}

// ③ 最小栈的「差值法」：不额外开栈，用 long 存编码值（面试追问时用）
class MinStackDiff {
    private final Deque<Long> st = new ArrayDeque<>();
    private long min = Long.MAX_VALUE;

    public void push(int v) {
        if (st.isEmpty()) { st.push(0L); min = v; }
        else {
            long diff = (long) v - min;      // 存「与当前最小值的差」
            st.push(diff);
            if (diff < 0) min = v;           // v 更小 → 更新最小值
        }
    }
    public void pop() {
        long diff = st.pop();
        if (diff < 0) min = min - diff;      // 还原出「上一个最小值」
    }
    public int top() {
        long diff = st.peek();
        return diff < 0 ? (int) min : (int) (min + diff);
    }
    public int getMin() { return (int) min; }
}

// ④ 用两个栈实现队列：in 负责入，out 负责出
class MyQueue {
    private final Deque<Integer> in = new ArrayDeque<>();
    private final Deque<Integer> out = new ArrayDeque<>();

    public void push(int x) { in.push(x); }

    public int pop() {
        transfer();               // 只在 out 空时才搬，保证「均摊 O(1)」
        return out.pop();
    }
    public int peek() { transfer(); return out.peek(); }
    public boolean empty() { return in.isEmpty() && out.isEmpty(); }

    private void transfer() {
        if (out.isEmpty()) {      // 关键条件：out 非空时不能搬，否则顺序会乱
            while (!in.isEmpty()) out.push(in.pop());
        }
    }
}

// ① 每日温度：找「右边第一个更高」的距离（栈内递减）
public int[] dailyTemperatures(int[] T) {
    int n = T.length;
    int[] ans = new int[n];               // 默认 0 = 后面没有更高的
    Deque<Integer> st = new ArrayDeque<>();   // 存下标
    for (int i = 0; i < n; i++) {
        while (!st.isEmpty() && T[i] > T[st.peek()]) {
            int j = st.pop();             // j 等到了它的答案
            ans[j] = i - j;               // 距离就是 i - j
        }
        st.push(i);
    }
    return ans;
}

// ② 下一个更大元素（不循环）：把「值」写进答案，逻辑完全一样
public int[] nextGreater(int[] a) {
    int n = a.length;
    int[] ans = new int[n];
    Arrays.fill(ans, -1);
    Deque<Integer> st = new ArrayDeque<>();
    for (int i = 0; i < n; i++) {
        while (!st.isEmpty() && a[i] > a[st.peek()]) ans[st.pop()] = a[i];
        st.push(i);
    }
    return ans;
}

// ③ 循环数组版：遍历 2n 次，用 i % n 取真实下标
public int[] nextGreaterCircular(int[] a) {
    int n = a.length;
    int[] ans = new int[n];
    Arrays.fill(ans, -1);
    Deque<Integer> st = new ArrayDeque<>();
    for (int i = 0; i < 2 * n; i++) {
        int idx = i % n;                  // 真实下标
        while (!st.isEmpty() && a[idx] > a[st.peek()]) {
            ans[st.pop()] = a[idx];
        }
        if (i < n) st.push(idx);          // 只在前 n 轮入栈，避免重复入栈
    }
    return ans;
}

// ④ 下一个更小（栈内递增，弹掉比它大的）
public int[] nextSmaller(int[] a) {
    int n = a.length;
    int[] ans = new int[n];
    Arrays.fill(ans, -1);
    Deque<Integer> st = new ArrayDeque<>();
    for (int i = 0; i < n; i++) {
        while (!st.isEmpty() && a[i] < a[st.peek()]) ans[st.pop()] = a[i];
        st.push(i);
    }
    return ans;
}

public int largestRectangleArea(int[] heights) {
    int n = heights.length;
    // 两端加高度 0 的哨兵：左边保证栈非空，右边保证全部弹出
    int[] h = new int[n + 2];
    System.arraycopy(heights, 0, h, 1, n);
    // h[0] = 0, h[n+1] = 0

    int ans = 0;
    Deque<Integer> st = new ArrayDeque<>();   // 存下标，栈内高度严格递增
    for (int i = 0; i < h.length; i++) {
        while (!st.isEmpty() && h[i] < h[st.peek()]) {
            int height = h[st.pop()];         // 弹出的这根 = 最矮的那根
            int left = st.peek();             // 左边界：弹完之后的新栈顶（可能是 0 号哨兵）
            int width = i - left - 1;         // 右边界是 i，左边界是 left
            ans = Math.max(ans, height * width);
        }
        st.push(i);
    }
    return ans;
}

// 对照：接雨水的单调栈版（按「行」算，横向分层）
public int trap(int[] height) {
    int n = height.length, ans = 0;
    Deque<Integer> st = new ArrayDeque<>();
    for (int i = 0; i < n; i++) {
        while (!st.isEmpty() && height[i] > height[st.peek()]) {
            int bottom = height[st.pop()];              // 凹槽的底
            if (st.isEmpty()) break;                    // 左边没有墙了
            int left = st.peek();
            int h = Math.min(height[left], height[i]) - bottom;   // 这一层的高度
            int w = i - left - 1;                                 // 这一层的宽度
            ans += h * w;
        }
        st.push(i);
    }
    return ans;
}

public int[] maxSlidingWindow(int[] a, int k) {
    int n = a.length;
    int[] ans = new int[n - k + 1];
    Deque<Integer> dq = new ArrayDeque<>();   // 存下标，对应值单调递减

    for (int i = 0; i < n; i++) {
        // ① 队头过期：下标 <= i - k 说明已滑出窗口
        while (!dq.isEmpty() && dq.peekFirst() <= i - k) dq.pollFirst();
        // ② 队尾劣汰：比新元素小的全部淘汰（它们永远等不到当最大值的机会）
        while (!dq.isEmpty() && a[dq.peekLast()] <= a[i]) dq.pollLast();
        // ③ 新元素入队
        dq.offerLast(i);
        // ④ 窗口形成后开始收集答案（队头就是当前窗口最大值）
        if (i >= k - 1) ans[i - k + 1] = a[dq.peekFirst()];
    }
    return ans;
}

// 对照：用大顶堆的版本（能过，但 O(n log n) 且有「延迟删除」问题）
public int[] maxSlidingWindowHeap(int[] a, int k) {
    int n = a.length;
    int[] ans = new int[n - k + 1];
    // 堆里存 {值, 下标}，按值降序
    PriorityQueue<int[]> pq = new PriorityQueue<>((x, y) -> y[0] - x[0]);
    for (int i = 0; i < n; i++) {
        pq.offer(new int[]{a[i], i});
        if (i >= k - 1) {
            // 延迟删除：堆顶可能已经过期，一直弹到有效为止
            while (pq.peek()[1] <= i - k) pq.poll();
            ans[i - k + 1] = pq.peek()[0];
        }
    }
    return ans;
}

public String decodeString(String s) {
    Deque<Integer> numStack = new ArrayDeque<>();
    Deque<StringBuilder> strStack = new ArrayDeque<>();
    StringBuilder cur = new StringBuilder();
    int num = 0;

    for (char c : s.toCharArray()) {
        if (c >= '0' && c <= '9') {
            num = num * 10 + (c - '0');            // 多位数字要累积
        } else if (c == '[') {
            numStack.push(num);                    // 存下「进入子问题前」的状态
            strStack.push(cur);
            num = 0;                               // 归零，别忘了
            cur = new StringBuilder();
        } else if (c == ']') {
            int k = numStack.pop();                // 重复次数
            StringBuilder prev = strStack.pop();   // 外层已积累的串
            StringBuilder repeated = new StringBuilder();
            for (int i = 0; i < k; i++) repeated.append(cur);   // 重复 k 次
            cur = prev.append(repeated);           // 接回外层
        } else {
            cur.append(c);                         // 普通字符直接累积
        }
    }
    return cur.toString();
}

// 递归写法对照：结构更接近「理解的顺序」，但深嵌套会爆栈
public String decodeStringRec(String s) {
    return decode(s, new int[]{0});
}
private String decode(String s, int[] pos) {
    StringBuilder sb = new StringBuilder();
    int num = 0;
    while (pos[0] < s.length()) {
        char c = s.charAt(pos[0]);
        if (c >= '0' && c <= '9') {
            num = num * 10 + (c - '0');
            pos[0]++;
        } else if (c == '[') {
            pos[0]++;                              // 跳过 '['
            String inner = decode(s, pos);          // 递归解析括号内
            for (int i = 0; i < num; i++) sb.append(inner);
            num = 0;
        } else if (c == ']') {
            pos[0]++;                              // 跳过 ']'
            return sb.toString();                   // 子问题结束，返回给上层
        } else {
            sb.append(c);
            pos[0]++;
        }
    }
    return sb.toString();
}

// ① 爬楼梯：dp[i] = 爬到第 i 阶的方法数（滚动变量版，O(1) 空间）
public int climbStairs(int n) {
    if (n <= 2) return n;
    int a = 1, b = 2;               // a = dp[i-2], b = dp[i-1]
    for (int i = 3; i <= n; i++) {
        int c = a + b;
        a = b;
        b = c;
    }
    return b;
}

// ② 打家劫舍：dp[i] = 偷前 i 家的最大金额（不偷相邻）
public int rob(int[] nums) {
    if (nums.length == 1) return nums[0];
    int prev2 = 0;                  // dp[i-2]：前 i-2 家的最优
    int prev1 = nums[0];            // dp[i-1]
    for (int i = 1; i < nums.length; i++) {
        int cur = Math.max(prev1, prev2 + nums[i]);   // 不偷 i / 偷 i（则跳过 i-1）
        prev2 = prev1;
        prev1 = cur;
    }
    return prev1;
}

// ③ 最大子数组和：dp[i] = 以 nums[i] 结尾的最大和（注意「以 i 结尾」）
public int maxSubArray(int[] nums) {
    int cur = nums[0];              // dp[i]
    int ans = nums[0];              // 答案不是 dp[n-1]，而是 max(dp[i])
    for (int i = 1; i < nums.length; i++) {
        cur = Math.max(nums[i], cur + nums[i]);   // 自己开头 / 接上前面
        ans = Math.max(ans, cur);
    }
    return ans;
}

// ④ 买卖股票（一次交易）：维护「历史最低价」，一遍扫描
public int maxProfit(int[] prices) {
    int minPrice = Integer.MAX_VALUE, ans = 0;
    for (int p : prices) {
        minPrice = Math.min(minPrice, p);   // 到昨天为止的最低价
        ans = Math.max(ans, p - minPrice);  // 今天卖出的最大利润
    }
    return ans;
}

// ⑤ 买卖股票（可多次交易）：只要「明天比今天高」就赚这一段
public int maxProfitMulti(int[] prices) {
    int ans = 0;
    for (int i = 1; i < prices.length; i++) {
        if (prices[i] > prices[i - 1]) ans += prices[i] - prices[i - 1];
    }
    return ans;
}

// ① 0-1 背包：每件物品最多一次 → 内层倒序
public int knapsack01(int[] w, int[] v, int C) {
    int[] dp = new int[C + 1];              // dp[j] = 容量 j 下的最大价值
    for (int i = 0; i < w.length; i++) {
        for (int j = C; j >= w[i]; j--) {   // 倒序：保证 dp[j-w] 是「上一轮」的值
            dp[j] = Math.max(dp[j], dp[j - w[i]] + v[i]);
        }
    }
    return dp[C];
}

// ② 完全背包：每件物品可用无限次 → 内层正序
public int knapsackComplete(int[] w, int[] v, int C) {
    int[] dp = new int[C + 1];
    for (int i = 0; i < w.length; i++) {
        for (int j = w[i]; j <= C; j++) {   // 正序：dp[j-w] 可能已用过当前物品
            dp[j] = Math.max(dp[j], dp[j - w[i]] + v[i]);
        }
    }
    return dp[C];
}

// ③ 零钱兑换（Q70）：完全背包求「最少硬币数」
public int coinChange(int[] coins, int amount) {
    int[] dp = new int[amount + 1];
    Arrays.fill(dp, amount + 1);            // 用 amount+1 当「无穷」，避免 MAX_VALUE+1 溢出
    dp[0] = 0;
    for (int coin : coins) {                // 外层物品
        for (int j = coin; j <= amount; j++) {   // 内层容量正序（硬币可重复用）
            dp[j] = Math.min(dp[j], dp[j - coin] + 1);
        }
    }
    return dp[amount] > amount ? -1 : dp[amount];
}

// ④ 组合数：凑出 amount 的组合个数（[1,2] 与 [2,1] 算一种）→ 外层物品
public int changeCombinations(int[] coins, int amount) {
    int[] dp = new int[amount + 1];
    dp[0] = 1;
    for (int coin : coins) {                        // 外层：物品
        for (int j = coin; j <= amount; j++) {      // 内层：容量
            dp[j] += dp[j - coin];
        }
    }
    return dp[amount];
}

// ⑤ 排列数：和为 amount 的排列个数（[1,2] 与 [2,1] 算两种）→ 外层容量
public int permutationCount(int[] nums, int target) {
    int[] dp = new int[target + 1];
    dp[0] = 1;
    for (int j = 1; j <= target; j++) {             // 外层：容量
        for (int x : nums) {                        // 内层：物品
            if (j >= x) dp[j] += dp[j - x];
        }
    }
    return dp[target];
}

// ① LIS：O(n^2) 的 DP（dp[i] = 以 nums[i] 结尾的 LIS 长度）
public int lengthOfLIS(int[] nums) {
    int n = nums.length, ans = 1;
    int[] dp = new int[n];
    Arrays.fill(dp, 1);
    for (int i = 1; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (nums[j] < nums[i]) dp[i] = Math.max(dp[i], dp[j] + 1);
        }
        ans = Math.max(ans, dp[i]);       // 答案不在 dp[n-1]，要全程取 max
    }
    return ans;
}

// ② LIS：O(n log n) 的贪心 + 二分（tails[k] = 长度 k+1 的最小结尾）
public int lengthOfLISFast(int[] nums) {
    int[] tails = new int[nums.length];
    int size = 0;                          // tails 的有效长度 = 当前 LIS 长度
    for (int x : nums) {
        int l = 0, r = size;               // 在 tails[0, size) 里找第一个 >= x
        while (l < r) {
            int mid = l + (r - l) / 2;
            if (tails[mid] < x) l = mid + 1;
            else                r = mid;
        }
        tails[l] = x;                      // 替换（或追加）
        if (l == size) size++;
    }
    return size;
}

// ③ LCS：最长公共子序列（不连续），二维 DP
public int longestCommonSubsequence(String a, String b) {
    int m = a.length(), n = b.length();
    int[][] dp = new int[m + 1][n + 1];    // dp[i][j] = a 前 i 个 与 b 前 j 个 的 LCS 长度
    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            if (a.charAt(i - 1) == b.charAt(j - 1)) {
                dp[i][j] = dp[i - 1][j - 1] + 1;          // 用上这个字符
            } else {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);   // 舍弃 a 的尾 或 b 的尾
            }
        }
    }
    return dp[m][n];
}

// ④ 最长公共子串（连续）：不等就清零，答案取全表最大值
public int longestCommonSubstring(String a, String b) {
    int m = a.length(), n = b.length(), ans = 0;
    int[][] dp = new int[m + 1][n + 1];
    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            if (a.charAt(i - 1) == b.charAt(j - 1)) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
                ans = Math.max(ans, dp[i][j]);            // 注意：答案要全程取 max
            }
            // 不相等时默认为 0（连续断了），不需要写
        }
    }
    return ans;
}

// 二维版：最清楚，面试首选
public int minDistance(String w1, String w2) {
    int m = w1.length(), n = w2.length();
    int[][] dp = new int[m + 1][n + 1];
    for (int i = 0; i <= m; i++) dp[i][0] = i;     // 全删
    for (int j = 0; j <= n; j++) dp[0][j] = j;     // 全插

    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            if (w1.charAt(i - 1) == w2.charAt(j - 1)) {
                dp[i][j] = dp[i - 1][j - 1];                     // 相等：不用操作
            } else {
                dp[i][j] = 1 + Math.min(
                    dp[i - 1][j - 1],                                 // 替换
                    Math.min(dp[i - 1][j], dp[i][j - 1])              // 删除 / 插入
                );
            }
        }
    }
    return dp[m][n];
}

// 一维压维版：O(n) 空间。关键是 diag 保存「左上角的旧值」
public int minDistance1D(String w1, String w2) {
    int m = w1.length(), n = w2.length();
    int[] dp = new int[n + 1];
    for (int j = 0; j <= n; j++) dp[j] = j;        // 第 0 行：全插入

    for (int i = 1; i <= m; i++) {
        int diag = dp[0];                          // 保存「上一轮的 dp[0]」，即左上角
        dp[0] = i;                                 // 第 0 列：全删除
        for (int j = 1; j <= n; j++) {
            int temp = dp[j];                      // 先存「本格的旧值（上一轮的 dp[j]）」
            if (w1.charAt(i - 1) == w2.charAt(j - 1)) {
                dp[j] = diag;
            } else {
                dp[j] = 1 + Math.min(diag, Math.min(dp[j], dp[j - 1]));
                //                            ↑上一轮同列      ↑本轮前一列
            }
            diag = temp;                           // 给下一格当「左上角」
        }
    }
    return dp[n];
}

// ① 中心扩展：O(n^2) 时间、O(1) 空间（推荐）
class LongestPalindrome {
    private int start = 0, maxLen = 1;

    public String longestPalindrome(String s) {
        if (s == null || s.length() < 2) return s;
        for (int i = 0; i < s.length() - 1; i++) {
            expand(s, i, i);       // 奇数长度：以 i 为中心
            expand(s, i, i + 1);   // 偶数长度：以 i 和 i+1 的间隙为中心
        }
        return s.substring(start, start + maxLen);
    }

    private void expand(String s, int l, int r) {
        while (l >= 0 && r < s.length() && s.charAt(l) == s.charAt(r)) {
            l--; r++;
        }
        // 循环退出时 [l+1, r-1] 是回文，长度 r - l - 1
        int len = r - l - 1;
        if (len > maxLen) {
            maxLen = len;
            start = l + 1;
        }
    }
}

// ② DP 版：dp[i][j] 表示 s[i..j] 是否回文（O(n^2) 空间，仅作对照）
public String longestPalindromeDp(String s) {
    int n = s.length();
    if (n < 2) return s;
    boolean[][] dp = new boolean[n][n];
    int start = 0, maxLen = 1;
    for (int i = 0; i < n; i++) dp[i][i] = true;             // 长度 1 都是回文

    for (int len = 2; len <= n; len++) {                     // 按「长度」枚举，保证 dp[i+1][j-1] 已算
        for (int i = 0; i + len - 1 < n; i++) {
            int j = i + len - 1;
            if (s.charAt(i) != s.charAt(j)) continue;
            dp[i][j] = (len == 2) || dp[i + 1][j - 1];        // 长度 2 直接算回文
            if (dp[i][j] && len > maxLen) {
                maxLen = len;
                start = i;
            }
        }
    }
    return s.substring(start, start + maxLen);
}

// ③ Manacher（O(n)）：预处理统一奇偶 + 复用对称半径
public String longestPalindromeManacher(String s) {
    StringBuilder sb = new StringBuilder("#");
    for (char c : s.toCharArray()) sb.append(c).append('#');
    String t = sb.toString();
    int n = t.length();
    int[] p = new int[n];          // p[i] = 以 i 为中心的回文半径
    int center = 0, right = 0;     // 当前「最右回文」的中心与右边界
    int bestLen = 0, bestCenter = 0;

    for (int i = 0; i < n; i++) {
        if (i < right) p[i] = Math.min(p[2 * center - i], right - i);   // 复用对称点
        while (i - p[i] - 1 >= 0 && i + p[i] + 1 < n
                && t.charAt(i - p[i] - 1) == t.charAt(i + p[i] + 1)) {
            p[i]++;
        }
        if (i + p[i] > right) {    // 更新最右回文
            center = i;
            right = i + p[i];
        }
        if (p[i] > bestLen) {
            bestLen = p[i];
            bestCenter = i;
        }
    }
    int start = (bestCenter - bestLen) / 2;   // 映射回原串下标
    return s.substring(start, start + bestLen);
}

// ① 栈解法：栈底是「最后一个未匹配的位置」
public int longestValidParentheses(String s) {
    Deque<Integer> st = new ArrayDeque<>();
    st.push(-1);                       // 虚拟基准
    int ans = 0;
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            st.push(i);
        } else {
            st.pop();
            if (st.isEmpty()) {
                st.push(i);            // 这个 ')' 不匹配，成为新的基准
            } else {
                ans = Math.max(ans, i - st.peek());   // 以 i 结尾的有效长度
            }
        }
    }
    return ans;
}

// ② 双向计数：O(1) 空间（只能求长度，不能定位）
public int longestValidParenthesesCount(String s) {
    int ans = 0;

    int left = 0, right = 0;           // 从左往右
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') left++; else right++;
        if (left == right)      ans = Math.max(ans, 2 * right);
        else if (right > left)  { left = 0; right = 0; }   // 右多了，不可能再配
    }

    left = 0; right = 0;               // 从右往左（对称规则）
    for (int i = s.length() - 1; i >= 0; i--) {
        if (s.charAt(i) == '(') left++; else right++;
        if (left == right)      ans = Math.max(ans, 2 * left);
        else if (left > right)  { left = 0; right = 0; }   // 左多了，不可能再配
    }
    return ans;
}

// ③ DP 解法（对照）：dp[i] = 以 i 结尾的最长有效长度
public int longestValidParenthesesDp(String s) {
    int n = s.length(), ans = 0;
    int[] dp = new int[n];
    for (int i = 1; i < n; i++) {
        if (s.charAt(i) != ')') continue;
        if (s.charAt(i - 1) == '(') {
            dp[i] = (i >= 2 ? dp[i - 2] : 0) + 2;
        } else {
            int j = i - dp[i - 1] - 1;                 // 跳过前面那一段，看更前面是不是 '('
            if (j >= 0 && s.charAt(j) == '(') {
                dp[i] = dp[i - 1] + 2 + (j >= 1 ? dp[j - 1] : 0);
            }
        }
        ans = Math.max(ans, dp[i]);
    }
    return ans;
}

// ① 字符串相加：竖式模拟
public String addStrings(String num1, String num2) {
    StringBuilder sb = new StringBuilder();
    int i = num1.length() - 1, j = num2.length() - 1, carry = 0;

    while (i >= 0 || j >= 0 || carry != 0) {   // carry != 0 保证最后的进位也被处理
        int a = (i >= 0) ? num1.charAt(i) - 48 : 0;   // 48 == '0' 的 ASCII
        int b = (j >= 0) ? num2.charAt(j) - 48 : 0;
        int sum = a + b + carry;
        sb.append((char) (sum % 10 + 48));
        carry = sum / 10;
        i--; j--;
    }
    return sb.reverse().toString();
}

// ② 字符串相乘：先累加到 res 数组，再统一处理进位
public String multiply(String num1, String num2) {
    if (num1.equals("0") || num2.equals("0")) return "0";
    int m = num1.length(), n = num2.length();
    int[] res = new int[m + n];               // 结果最多 m+n 位

    // 关键：num1[i] * num2[j] 落在 res[i + j + 1]
    for (int i = m - 1; i >= 0; i--) {
        for (int j = n - 1; j >= 0; j--) {
            int mul = (num1.charAt(i) - 48) * (num2.charAt(j) - 48);
            int p1 = i + j, p2 = i + j + 1;
            int sum = mul + res[p2];          // 加上这一位已有的累加值
            res[p2] = sum % 10;
            res[p1] += sum / 10;              // 进位先累加，不急着处理
        }
    }

    StringBuilder sb = new StringBuilder();
    for (int x : res) {
        if (!(sb.length() == 0 && x == 0)) sb.append((char) (x + 48));   // 跳过前导零
    }
    return sb.length() == 0 ? "0" : sb.toString();
}

// ③ 通用版：如果数字里可能有负号，先处理符号再调上面的方法
public String addGeneral(String a, String b) {
    boolean negA = a.startsWith("-"), negB = b.startsWith("-");
    String absA = negA ? a.substring(1) : a;
    String absB = negB ? b.substring(1) : b;
    if (negA == negB) {                       // 同号：相加后补符号
        return (negA ? "-" : "") + addStrings(absA, absB);
    }
    // 异号：绝对值大的减绝对值小的，符号取绝对值大的
    int cmp = compareAbs(absA, absB);
    if (cmp == 0) return "0";
    if (cmp > 0) return (negA ? "-" : "") + subtractStrings(absA, absB);
    return (negB ? "-" : "") + subtractStrings(absB, absA);
}
private int compareAbs(String a, String b) {
    if (a.length() != b.length()) return a.length() - b.length();
    return a.compareTo(b);
}
private String subtractStrings(String a, String b) {   // 要求 a >= b
    StringBuilder sb = new StringBuilder();
    int i = a.length() - 1, j = b.length() - 1, borrow = 0;
    while (i >= 0) {
        int x = a.charAt(i) - 48 - borrow - (j >= 0 ? b.charAt(j) - 48 : 0);
        if (x < 0) { x += 10; borrow = 1; } else { borrow = 0; }
        sb.append((char) (x + 48));
        i--; j--;
    }
    String r = sb.reverse().toString();
    int k = 0;
    while (k < r.length() - 1 && r.charAt(k) == '0') k++;   // 去前导零
    return r.substring(k);
}

class LFUCache {
    // 桶内双向链表节点
    class Node {
        int k, v, freq;
        Node prev, next;
        Node(int k, int v) { this.k = k; this.v = v; this.freq = 1; }
    }
    // 一个频次对应的双向链表（头部 = 该频次内最近使用）
    class Bucket {
        Node head = new Node(0, 0), tail = new Node(0, 0);
        int size = 0;
        Bucket() { head.next = tail; tail.prev = head; }
        void addFirst(Node n) {
            n.next = head.next; n.prev = head;
            head.next.prev = n; head.next = n;
            size++;
        }
        void remove(Node n) {
            n.prev.next = n.next; n.next.prev = n.prev;
            size--;
        }
        Node removeLast() {
            if (size == 0) return null;
            Node n = tail.prev;
            remove(n);
            return n;
        }
    }

    private final int capacity;
    private int minFreq = 0;
    private final Map<Integer, Node> keyToNode = new HashMap<>();
    private final Map<Integer, Bucket> freqToBucket = new HashMap<>();

    public LFUCache(int capacity) { this.capacity = capacity; }

    public int get(int key) {
        Node n = keyToNode.get(key);
        if (n == null) return -1;
        touch(n);                      // 频次 +1 并搬家
        return n.v;
    }

    public void put(int key, int value) {
        if (capacity == 0) return;
        Node n = keyToNode.get(key);
        if (n != null) {
            n.v = value;
            touch(n);
            return;
        }
        if (keyToNode.size() == capacity) {
            Bucket b = freqToBucket.get(minFreq);
            Node victim = b.removeLast();    // 淘汰「最小频次里最久未用」的那个
            keyToNode.remove(victim.k);
        }
        Node node = new Node(key, value);
        node.freq = 1;
        keyToNode.put(key, node);
        freqToBucket.computeIfAbsent(1, x -> new Bucket()).addFirst(node);
        minFreq = 1;                        // 新插入的频次必然是 1，最小频次重置为 1
    }

    // 把节点从 freq 桶移到 freq+1 桶
    private void touch(Node n) {
        Bucket oldBucket = freqToBucket.get(n.freq);
        oldBucket.remove(n);
        // 关键：只有「桶空了」且「它就是最小频次」才递增 minFreq
        if (oldBucket.size == 0 && n.freq == minFreq) minFreq++;
        n.freq++;
        freqToBucket.computeIfAbsent(n.freq, x -> new Bucket()).addFirst(n);
    }
}

class Trie {
    private static class Node {
        Node[] children = new Node[26];   // 26 个小写字母；也可以换成 HashMap
        boolean isEnd = false;            // 标记「这里是不是某个词的结尾」
    }
    private final Node root = new Node();

    public void insert(String word) {
        Node cur = root;
        for (char c : word.toCharArray()) {
            int i = c - 'a';
            if (cur.children[i] == null) cur.children[i] = new Node();
            cur = cur.children[i];
        }
        cur.isEnd = true;                 // 别忘了这一句，否则 search 永远返回 false
    }

    public boolean search(String word) {
        Node n = walk(word);
        return n != null && n.isEnd;      // 必须同时判「走到了」和「是词尾」
    }

    public boolean startsWith(String prefix) {
        return walk(prefix) != null;      // 只要走到了就是前缀，不判 isEnd
    }

    private Node walk(String s) {
        Node cur = root;
        for (char c : s.toCharArray()) {
            int i = c - 'a';
            if (cur.children[i] == null) return null;
            cur = cur.children[i];
        }
        return cur;
    }
}

// 应用 ①：统计「以某前缀开头的词有多少个」——在节点上加 count
class TrieWithCount {
    private static class Node {
        Node[] children = new Node[26];
        int pass = 0;                     // 有多少个词「经过」这个节点
        int end = 0;                      // 有多少个词「在这里结束」
    }
    private final Node root = new Node();

    void insert(String w) {
        Node cur = root;
        for (char c : w.toCharArray()) {
            int i = c - 'a';
            if (cur.children[i] == null) cur.children[i] = new Node();
            cur = cur.children[i];
            cur.pass++;                   // 路径上每个节点的 pass 都 +1
        }
        cur.end++;
    }
    int countPrefix(String p) {
        Node cur = root;
        for (char c : p.toCharArray()) {
            int i = c - 'a';
            if (cur.children[i] == null) return 0;
            cur = cur.children[i];
        }
        return cur.pass;
    }
}

// 应用 ②：单词搜索（网格 DFS + Trie 剪枝）
public List<String> findWords(char[][] board, String[] words) {
    Trie trie = new Trie();
    for (String w : words) trie.insert(w);

    Set<String> res = new HashSet<>();
    int R = board.length, C = board[0].length;
    for (int i = 0; i < R; i++)
        for (int j = 0; j < C; j++)
            dfs(board, i, j, trie.root, new StringBuilder(), res);
    return new ArrayList<>(res);
}
private void dfs(char[][] b, int i, int j, Trie.Node node, StringBuilder path, Set<String> res) {
    if (i < 0 || i >= b.length || j < 0 || j >= b[0].length) return;
    char c = b[i][j];
    if (c == '#' || node.children[c - 'a'] == null) return;   // '#' = 已访问
    node = node.children[c - 'a'];
    path.append(c);
    if (node.isEnd) res.add(path.toString());
    b[i][j] = '#';                                            // 标记访问
    dfs(b, i + 1, j, node, path, res);
    dfs(b, i - 1, j, node, path, res);
    dfs(b, i, j + 1, node, path, res);
    dfs(b, i, j - 1, node, path, res);
    b[i][j] = c;                                              // 回溯
    path.deleteCharAt(path.length() - 1);                     // 回溯
}

// 外排序：① 分块排序落盘 → ② 多路归并（小顶堆）
// 假设每块 100MB，100GB 就是 1000 块
public class ExternalSort {

    // 第一步：把大文件切成 K 块，每块读进内存排好序，写成临时文件
    public List<File> splitAndSort(File input, int chunkSizeBytes) throws IOException {
        List<File> chunks = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new FileReader(input), 1 << 20)) {
            List<Integer> buf = new ArrayList<>();
            int approxBytes = 0;
            String line;
            while ((line = reader.readLine()) != null) {
                buf.add(Integer.parseInt(line));
                approxBytes += line.length() + 1;
                if (approxBytes >= chunkSizeBytes) {
                    chunks.add(writeSortedChunk(buf));   // 内存内排序 + 落盘
                    buf.clear();
                    approxBytes = 0;
                }
            }
            if (!buf.isEmpty()) chunks.add(writeSortedChunk(buf));
        }
        return chunks;
    }

    private File writeSortedChunk(List<Integer> buf) throws IOException {
        Collections.sort(buf);                          // 块内排序（内存排序）
        File f = File.createTempFile("chunk", ".txt");
        try (BufferedWriter w = new BufferedWriter(new FileWriter(f), 1 << 20)) {
            for (int x : buf) { w.write(Integer.toString(x)); w.newLine(); }
        }
        return f;
    }

    // 第二步：多路归并——K 个文件的当前行放进小顶堆，每次取最小
    // 关键：不是「两两归并」（那要 log K 轮 IO），而是一次性 K 路归并（只要 1 轮）
    public void merge(List<File> chunks, File output) throws IOException {
        // 小顶堆元素：{值, 来自哪个文件的第几个读取器}
        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        List<BufferedReader> readers = new ArrayList<>();
        List<BufferedWriter> dummy = null;              // 占位，说明只读

        try (BufferedWriter w = new BufferedWriter(new FileWriter(output), 1 << 20)) {
            for (int i = 0; i < chunks.size(); i++) {
                BufferedReader r = new BufferedReader(new FileReader(chunks.get(i)), 1 << 16);
                readers.add(r);
                String first = r.readLine();
                if (first != null) heap.offer(new int[]{Integer.parseInt(first), i});
            }
            while (!heap.isEmpty()) {
                int[] top = heap.poll();
                w.write(Integer.toString(top[0]));
                w.newLine();
                String next = readers.get(top[1]).readLine();   // 从同一个文件补下一个
                if (next != null) heap.offer(new int[]{Integer.parseInt(next), top[1]});
            }
        } finally {
            for (BufferedReader r : readers) r.close();
            for (File f : chunks) f.delete();
        }
    }

    // 内存核算（面试要能当场报出来）：
    // - 每块 100MB 读进内存排序：峰值 100MB（+ 排序辅助 ≈ 200MB），远小于 1GB
    // - 多路归并：1000 个文件各开一个 BufferedReader（每个 64KB 缓冲）≈ 64MB
    // - 小顶堆：1000 个元素，可忽略
    // - IO 次数：分块 1 读 1 写 + 归并 1 读 1 写 = 4 次；若两两归并则 log2(1000) ≈ 10 轮
}

// ① wait/notify 版：最基础，考点全在「while」和「notifyAll」
class PrintAbcSync {
    private int state = 0;                      // 0→打印A, 1→B, 2→C
    private final int n;                        // 每轮打印几次
    PrintAbcSync(int n) { this.n = n; }

    public synchronized void print(char c, int target) throws InterruptedException {
        for (int i = 0; i < n; i++) {
            while (state != target) wait();      // 必须是 while
            System.out.print(c);
            state = (state + 1) % 3;
            notifyAll();                         // 用 notifyAll，别用 notify
        }
    }
}

// ② ReentrantLock + 单个 Condition（本质同 ①，只是换 API）
class PrintAbcLock {
    private final Lock lock = new ReentrantLock();
    private final Condition cond = lock.newCondition();
    private int state = 0;
    private final int n;
    PrintAbcLock(int n) { this.n = n; }

    public void print(char c, int target) throws InterruptedException {
        for (int i = 0; i < n; i++) {
            lock.lock();
            try {
                while (state != target) cond.await();
                System.out.print(c);
                state = (state + 1) % 3;
                cond.signalAll();
            } finally {
                lock.unlock();                   // 必须在 finally
            }
        }
    }
}

// ③ Semaphore 版：最简洁——每个线程一个许可，打完把下一个的许可放出来
class PrintAbcSemaphore {
    private final Semaphore sA = new Semaphore(1);   // A 先跑
    private final Semaphore sB = new Semaphore(0);
    private final Semaphore sC = new Semaphore(0);
    private final int n;
    PrintAbcSemaphore(int n) { this.n = n; }

    void printA() throws InterruptedException { loop('A', sA, sB); }
    void printB() throws InterruptedException { loop('B', sB, sC); }
    void printC() throws InterruptedException { loop('C', sC, sA); }
    private void loop(char c, Semaphore cur, Semaphore next) throws InterruptedException {
        for (int i = 0; i < n; i++) {
            cur.acquire();                   // 等自己的许可
            System.out.print(c);
            next.release();                  // 放下一个的许可
        }
    }
}

// ④ LockSupport 版：最灵活（可以在任意位置 park/unpark，不要求在锁内）
class PrintAbcPark {
    private final Thread[] ts = new Thread[3];
    private final int n;
    PrintAbcPark(int n) { this.n = n; }

    void start() {
        char[] cs = {'A', 'B', 'C'};
        for (int i = 0; i < 3; i++) {
            final int idx = i;
            ts[i] = new Thread(() -> {
                for (int k = 0; k < n; k++) {
                    LockSupport.park();      // 先阻塞自己
                    System.out.print(cs[idx]);
                    LockSupport.unpark(ts[(idx + 1) % 3]);   // 唤醒下一个
                }
            });
            ts[i].start();
        }
        LockSupport.unpark(ts[0]);           // 手动启动 A
    }
}

// ① 两个线程交替打印 1~100（奇数 / 偶数）
class PrintOddEven {
    private int num = 1;
    private final int max;

    PrintOddEven(int max) { this.max = max; }

    public synchronized void print(int parity) throws InterruptedException {   // parity: 1=奇, 0=偶
        while (num <= max) {
            // 用 while 而不是 if：既要判「还没到我的turn」，也要判「已经打完了」
            while (num <= max && num % 2 != (parity == 1 ? 1 : 0)) wait();
            if (num > max) { notifyAll(); return; }     // 结束时唤醒对方一起退出
            System.out.print(num++ + " ");
            notifyAll();
        }
    }
}
// 调用：t1 跑 print(1)，t2 跑 print(0)

// ② 三线程顺序执行 A→B→C（每个线程只打印一次，但要求严格顺序）
// 方案一：join 链（最简单，但「顺序」是靠「等线程结束」，不适合循环场景）
Thread tA = new Thread(() -> System.out.print("A"));
Thread tB = new Thread(() -> { try { tA.join(); } catch (InterruptedException e) {} System.out.print("B"); });
Thread tC = new Thread(() -> { try { tB.join(); } catch (InterruptedException e) {} System.out.print("C"); });

// 方案二：CountDownLatch 链（更通用，可以控「等几个」）
CountDownLatch l1 = new CountDownLatch(1), l2 = new CountDownLatch(1);
new Thread(() -> { System.out.print("A"); l1.countDown(); }).start();
new Thread(() -> { try { l1.await(); } catch (InterruptedException e) {} System.out.print("B"); l2.countDown(); }).start();
new Thread(() -> { try { l2.await(); } catch (InterruptedException e) {} System.out.print("C"); }).start();

// 方案三：单线程池（如果「顺序执行」是需求而不是考点，这才是工程答案）
ExecutorService single = Executors.newSingleThreadExecutor();
single.submit(() -> System.out.print("A"));
single.submit(() -> System.out.print("B"));
single.submit(() -> System.out.print("C"));
single.shutdown();

// 手写线程池：能说清「取任务 → 执行 → 空闲回收」这个循环就够了
public class SimpleThreadPool {
    private final int coreSize;
    private final int maxSize;
    private final BlockingQueue<Runnable> queue;
    private final Set<Worker> workers = ConcurrentHashMap.newKeySet();
    private final AtomicInteger total = new AtomicInteger(0);   // 当前线程数
    private volatile boolean shutdown = false;

    public SimpleThreadPool(int coreSize, int maxSize, int queueCapacity) {
        this.coreSize = coreSize;
        this.maxSize = maxSize;
        this.queue = new ArrayBlockingQueue<>(queueCapacity);   // 有界队列，关键
    }

    public void execute(Runnable task) {
        if (shutdown) throw new RejectedExecutionException("pool is shutdown");

        // ① 未到核心数：直接新建核心线程
        if (total.get() < coreSize) {
            if (addWorker(task)) return;
        }
        // ② 尝试入队（这一步在「扩容」之前，和 ThreadPoolExecutor 一致）
        if (queue.offer(task)) return;
        // ③ 队列满：尝试扩容到 max
        if (total.get() < maxSize) {
            if (addWorker(task)) return;
        }
        // ④ 都满了：拒绝（这里用「调用者自己跑」当背压）
        new Thread(task, "caller-runs").start();
    }

    private boolean addWorker(Runnable firstTask) {
        total.incrementAndGet();
        Worker w = new Worker(firstTask);
        workers.add(w);
        w.t.start();
        return true;
    }

    private final class Worker implements Runnable {
        final Thread t;
        Runnable firstTask;

        Worker(Runnable firstTask) {
            this.firstTask = firstTask;
            this.t = new Thread(this, "pool-worker-" + total.get());
        }

        @Override
        public void run() {
            try {
                Runnable task = firstTask;
                firstTask = null;
                while (task != null || (task = getTask()) != null) {
                    try {
                        task.run();
                    } catch (RuntimeException e) {
                        // 任务异常不能打死 worker：捕获并继续
                    } finally {
                        task = null;
                    }
                }
            } finally {
                workers.remove(this);       // 退出时从集合里摘掉
                total.decrementAndGet();
            }
        }

        // 取任务：核心线程一直等；非核心线程「有空闲超时就退出」
        private Runnable getTask() {
            try {
                if (total.get() > coreSize) {
                    return queue.poll(1, TimeUnit.SECONDS);   // 非核心：超时返回 null → 退出
                }
                return queue.take();                          // 核心：一直等
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return null;
            }
        }
    }

    public void shutdown() {
        shutdown = true;
        for (Worker w : workers) w.t.interrupt();   // 打断阻塞的 take/poll
    }
}

public class DeadlockDemo {
    private static final Object LOCK_A = new Object();
    private static final Object LOCK_B = new Object();

    public static void main(String[] args) {
        Thread t1 = new Thread(() -> {
            synchronized (LOCK_A) {
                System.out.println("t1 got A");
                sleep(100);                       // 给 t2 机会拿到 B
                synchronized (LOCK_B) { System.out.println("t1 got B"); }
            }
        }, "Thread-1");

        Thread t2 = new Thread(() -> {
            synchronized (LOCK_B) {               // 注意：顺序相反
                System.out.println("t2 got B");
                sleep(100);
                synchronized (LOCK_A) { System.out.println("t2 got A"); }
            }
        }, "Thread-2");

        t1.start(); t2.start();
    }

    private static void sleep(long ms) {
        try { Thread.sleep(ms); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    }
}

