// 线程安全的本地缓存：ConcurrentHashMap + 双向链表（LRU）+ 惰性过期
public class LocalCache<K, V> {

    private static final class Node<K, V> {
        K key; V val;
        long expireAt;                 // 绝对过期时间戳（0 = 永不过期）
        Node<K, V> prev, next;
        Node(K k, V v, long expireAt) { this.key = k; this.val = v; this.expireAt = expireAt; }
    }

    private final int capacity;
    private final long ttlMillis;      // 0 = 不过期
    private final Map<K, Node<K, V>> map = new ConcurrentHashMap<>();
    private final Node<K, V> head = new Node<>(null, null, 0);   // 哨兵：最近使用
    private final Node<K, V> tail = new Node<>(null, null, 0);   // 哨兵：最久未用
    private final Object lock = new Object();                    // 只保护链表

    public LocalCache(int capacity, long ttlMillis) {
        this.capacity = capacity;
        this.ttlMillis = ttlMillis;
        head.next = tail;
        tail.prev = head;
    }

    public V get(K key) {
        Node<K, V> n = map.get(key);
        if (n == null) return null;
        if (isExpired(n)) {                       // 惰性删除
            removeNode(n);
            map.remove(key, n);                   // 带 value 比较，防误删新值
            return null;
        }
        synchronized (lock) { moveToHead(n); }    // 链表操作要加锁
        return n.val;
    }

    public void put(K key, V val) {
        long expireAt = (ttlMillis > 0) ? System.currentTimeMillis() + ttlMillis : 0;
        Node<K, V> n = new Node<>(key, val, expireAt);
        Node<K, V> old = map.put(key, n);
        if (old != null) {                        // 覆盖：先摘掉旧节点
            synchronized (lock) { unlink(old); }
        }
        synchronized (lock) {
            linkToHead(n);                        // 新节点放头部
            if (map.size() > capacity) {          // 超容量：淘汰尾部
                Node<K, V> victim = tail.prev;
                if (victim != head) {
                    unlink(victim);
                    map.remove(victim.key, victim);
                }
            }
        }
    }

    private boolean isExpired(Node<K, V> n) {
        return n.expireAt != 0 && System.currentTimeMillis() > n.expireAt;
    }

    // 以下三个方法都必须在 lock 内调用
    private void unlink(Node<K, V> n) {
        n.prev.next = n.next;
        n.next.prev = n.prev;
    }
    private void linkToHead(Node<K, V> n) {
        n.next = head.next; n.prev = head;
        head.next.prev = n; head.next = n;
    }
    private void moveToHead(Node<K, V> n) { unlink(n); linkToHead(n); }

    // 兜底清理：定时抽样（模拟 Redis 的定期删除）
    public void evictExpired(int sampleSize) {
        int checked = 0, expired = 0;
        for (Node<K, V> n : map.values()) {
            if (checked++ >= sampleSize) break;
            if (isExpired(n)) { expired++; removeNode(n); map.remove(n.key, n); }
        }
        // 抽到的样本里过期比例高，就说明该继续清（这里简化成「一次抽样」）
    }
    private void removeNode(Node<K, V> n) { synchronized (lock) { unlink(n); } }
}
